/**
 * GraphQL documents for the Indeed employer API (apis.indeed.com/graphql),
 * extracted verbatim from the discovery run 2026-09-29
 * (docs/discovery-2026-09-29.md). Full query text is sent by the dashboard
 * itself, so these replay exactly. If Indeed changes a schema and a query
 * starts failing, re-run `indeed-axi discover` and re-extract.
 */
/** findEmployerJobs
 * variables: { input: { limit, filter } }
 */
export const findEmployerJobs = "query FindEmployerJobs($input: FindEmployerJobsInput!) {\n  findEmployerJobs(input: $input) {\n    results {\n      employerJob {\n        id\n        jobData {\n          id\n          title\n          ... on HostedJobPost {\n            legacyId\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    estimatedTotalResultsCount\n    __typename\n  }\n}\n";
/** findCandidateSubmissions
 * variables: { input: { filter: { jobs: { employerJobIds }, hiringMilestones, submissionType } }, first }
 */
export const findCandidateSubmissions = "query CandidateListIds($input: FindCandidateSubmissionsInput!, $first: Int) {\n  findCandidateSubmissions(input: $input, first: $first) {\n    candidateSubmissions {\n      id\n      data {\n        ... on EmployerGeneratedCandidateSubmission {\n          legacyID\n          __typename\n        }\n        ... on HiddenEmployerGeneratedCandidateSubmission {\n          legacyID\n          __typename\n        }\n        ... on HiddenIndeedApplyCandidateSubmission {\n          legacyID\n          __typename\n        }\n        ... on IndeedApplyCandidateSubmission {\n          legacyID\n          __typename\n        }\n        profile {\n          name {\n            displayName\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n}\n";
/** getCandidateSubmission
 * variables: { input: { legacyIds: [<hex>] } }
 */
export const getCandidateSubmission = "query GetCandidateSubmission($input: CandidateSubmissionsInput!) {\n  candidateSubmissions(input: $input) {\n    results {\n      ...CandidateSubmissionFields\n      __typename\n    }\n    __typename\n  }\n}\n\nfragment CandidateSubmissionFields on CandidateSubmission {\n  id\n  data {\n    created\n    profile {\n      name {\n        displayName\n        __typename\n      }\n      contact {\n        phoneNumber\n        __typename\n      }\n      __typename\n    }\n    milestone {\n      milestone {\n        category\n        milestoneId\n        __typename\n      }\n      __typename\n    }\n    feedback(first: 1, input: {filter: {feedbackType: [INTEREST_LEVEL]}}) {\n      feedback {\n        id\n        ... on EmployerCandidateSentiment {\n          interestLevel\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    jobs {\n      jobs {\n        id\n        jobData {\n          id\n          ... on HostedJobPost {\n            legacyId\n            jobKey\n            __typename\n          }\n          location {\n            formatted {\n              short\n              __typename\n            }\n            __typename\n          }\n          advertisingLocations {\n            publicJobPageUrl\n            location\n            __typename\n          }\n          title\n          externalJobPageUrl\n          description\n          company\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    candidateIdentity {\n      candidateId\n      jobseekerAccountKey\n      candidate {\n        id\n        __typename\n      }\n      __typename\n    }\n    ... on EmployerGeneratedCandidateSubmission {\n      legacyID\n      __typename\n    }\n    ... on IndeedApplyCandidateSubmission {\n      legacyID\n      __typename\n    }\n    submissionUuid\n    __typename\n  }\n  __typename\n}\n";
/** originalApplicationData
 * variables: { input: { submissionUuid } }
 */
export const originalApplicationData = "query OriginalApplicationData($input: OriginalApplicationDataInput!) {\n  originalApplicationData(input: $input) {\n    applicationPreview {\n      __typename\n      attachmentCookie\n      html\n      fileName\n    }\n    attachments {\n      __typename\n      downloadUrl\n      fileId\n      fileName\n      mimeType\n    }\n    postBody {\n      __typename\n      downloadUrl\n      fileId\n      fileName\n      mimeType\n    }\n    __typename\n  }\n}\n";
/** getConversationAndEvents
 * variables: { conversationId, includeRequireResponse, timelineModuleInput }
 */
export const getConversationAndEvents = "query GetConversationAndEvents($conversationId: ID!, $expectedRecipientEmailHash: String, $first: Int, $after: String, $last: Int, $before: String, $timelineModuleInput: TimelineModuleInput!, $includeRequireResponse: Boolean = false) {\n  conversation(\n    input: {conversationId: $conversationId, expectedRecipientEmailHash: $expectedRecipientEmailHash}\n  ) {\n    ...ConversationDetailFields\n    isBroadcastEnabled\n    isParticipantManagementEnabled\n    moderationStatus\n    eventsConnection(first: $first, after: $after, last: $last, before: $before) {\n      edges {\n        node {\n          ...ConversationEventListItem\n          __typename\n        }\n        __typename\n      }\n      pageInfo {\n        startCursor\n        endCursor\n        hasNextPage\n        hasPreviousPage\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n}\n\nfragment ConversationDetailFields on Conversation {\n  ...ConversationPreviewFields\n  participants {\n    accessLevel\n    employerUser {\n      id\n      account {\n        id\n        accountProfile {\n          email {\n            emailAddress\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    peripheralAccount {\n      id\n      accountProfile {\n        email {\n          emailAddress\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n  recipients {\n    recipientName\n    role\n    accountKey\n    __typename\n  }\n  userReadsInfo {\n    lastVisited\n    readCursor\n    __typename\n  }\n  payload {\n    key\n    value\n    __typename\n  }\n  userContext {\n    jobApplication {\n      applyTime\n      __typename\n    }\n    __typename\n  }\n  __typename\n}\n\nfragment ConversationPreviewFields on Conversation {\n  id\n  __typename\n  title\n  creationDateTime\n  context\n  scope {\n    key\n    value\n    __typename\n  }\n  lastEvent {\n    id\n    author {\n      accountKey\n      externalParticipantId\n      role\n      __typename\n    }\n    type\n    subType\n    messageContentFormat\n    messagePreview\n    publicationDateTime\n    __typename\n  }\n  participants {\n    accountKey\n    externalParticipantId\n    isApp\n    participantName\n    removed\n    role\n    __typename\n  }\n  userReadsInfo {\n    unreadCount\n    __typename\n  }\n  userLabelInfo {\n    labels\n    __typename\n  }\n  locks {\n    primary\n    reason\n    reasonCode\n    timestamp\n    endUserDisplayText\n    isRemovable\n    __typename\n  }\n  job {\n    key\n    displayTitle\n    normalizedTitle\n    title\n    employer {\n      key\n      name\n      dossier {\n        images {\n          squareLogoUrls {\n            url64\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    location {\n      formatted {\n        short\n        __typename\n      }\n      __typename\n    }\n    sourceEmployerName\n    __typename\n  }\n  userContext {\n    participantKey\n    requireResponse @include(if: $includeRequireResponse) {\n      required\n      timestamp\n      __typename\n    }\n    __typename\n  }\n  jobIsConfirmedFraudulent\n}\n\nfragment ConversationEventListItem on ConversationEvent {\n  ...ConversationEventListItemWithoutTimelineModuleResult\n  timelineModuleResult(input: $timelineModuleInput) {\n    __typename\n    ... on TimelineModule {\n      telContent\n      data\n      timelineModuleType\n      overrides {\n        sender\n        message\n        __typename\n      }\n      __typename\n    }\n    ... on TimelineModuleError {\n      code\n      message\n      __typename\n    }\n  }\n  __typename\n}\n\nfragment ConversationEventListItemWithoutTimelineModuleResult on ConversationEvent {\n  id\n  cleanedMessageBody\n  type\n  messageBody\n  messageContentFormat\n  messagePreview\n  metadata {\n    key\n    value\n    __typename\n  }\n  publicationDateTime\n  payload {\n    key\n    value\n    __typename\n  }\n  attachments {\n    contentHash\n    fileSid\n    fileName\n    fileExtension\n    __typename\n  }\n  author {\n    accountKey\n    externalParticipantId\n    role\n    __typename\n  }\n  subType\n  __typename\n}\n";
/** findConversationsByCandidateKey
 * variables: { advertiserKey, candidateKey, enableAdjacentContextSearch }
 */
export const findConversationsByCandidateKey = "query FindConversationsByCandidateKey($advertiserKey: String!, $candidateKey: String!, $enableAdjacentContextSearch: Boolean = false) {\n  findConversations(\n    input: {filter: {contexts: [APPLICATION, HQM], scope: [{key: ADVERTISER_KEY, value: $advertiserKey}, {key: CANDIDATE_KEY, value: $candidateKey}]}, options: {adjacentContextSearch: $enableAdjacentContextSearch, allowUninitiatedConversationResults: true}}\n  ) {\n    conversations {\n      id\n      creationDateTime\n      __typename\n    }\n    __typename\n  }\n}\n";
/** unreadConversationCount
 * variables: {}
 */
export const unreadConversationCount = "query UnreadConversationCount {\n  getUnreadConversationCount(\n    input: {conversationFilter: {contexts: [APPLICATION, RESUME_CONTACT, HQM, HQM_PREAPPLY]}, maxCountLimit: 10}\n  ) {\n    unreadConversationCount\n    __typename\n  }\n}\n";
/** getCurrentEmployerUser
 * variables: {}
 * yields data.currentEmployerUser.employer.employerId (the advertiserKey)
 */
export const getCurrentEmployerUser = "query GetCurrentEmployerUser {\n  currentEmployerUser {\n    id\n    account {\n      id\n      __typename\n    }\n    employer {\n      id\n      employerId\n      __typename\n    }\n    permissions {\n      hostedCandidate {\n        read\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n}\n";
/** sendConversationEvent
 * variables: {messageBody, context: {context, scope: {preOrPostApply: {advertiserKey, aggJobKey, candidateKey}}}, eventId, correlationKey, clientName: "messaging-react", attachments: [], payload: [], includeRequireResponse: false}
 */
export const sendConversationEvent = "mutation SendConversationEvent($attachments: [ConversationAttachmentInput!], $clientName: String!, $conversationId: ID, $context: ConversationContextAndScopeInput, $correlationKey: String, $eventId: String, $includeRequireResponse: Boolean = false, $messageBody: String!, $payload: [ConversationEventMetadataInput!], $reminders: ConversationEventRemindersInput, $replyToEventId: ID) {\n  sendConversationEvent(\n    input: {attachments: $attachments, conversation: {id: $conversationId, contextAndScope: $context}, correlationKey: $correlationKey, eventId: $eventId, messageBody: $messageBody, messageContentFormat: \"PLAIN\", source: $clientName, type: MESSAGE, payload: $payload, reminders: $reminders, replyToEventId: $replyToEventId}\n  ) {\n    conversationId\n    conversation {\n      ...ConversationDetailFields\n      __typename\n    }\n    correlationKey\n    event {\n      ...ConversationEventListItemWithoutTimelineModuleResult\n      __typename\n    }\n    __typename\n  }\n}\n\nfragment ConversationDetailFields on Conversation {\n  ...ConversationPreviewFields\n  participants {\n    accessLevel\n    employerUser {\n      id\n      account {\n        id\n        accountProfile {\n          email {\n            emailAddress\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    peripheralAccount {\n      id\n      accountProfile {\n        email {\n          emailAddress\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n  recipients {\n    recipientName\n    role\n    accountKey\n    __typename\n  }\n  userReadsInfo {\n    lastVisited\n    readCursor\n    __typename\n  }\n  payload {\n    key\n    value\n    __typename\n  }\n  userContext {\n    jobApplication {\n      applyTime\n      __typename\n    }\n    __typename\n  }\n  __typename\n}\n\nfragment ConversationPreviewFields on Conversation {\n  id\n  __typename\n  title\n  creationDateTime\n  context\n  scope {\n    key\n    value\n    __typename\n  }\n  lastEvent {\n    id\n    author {\n      accountKey\n      externalParticipantId\n      role\n      __typename\n    }\n    type\n    subType\n    messageContentFormat\n    messagePreview\n    publicationDateTime\n    __typename\n  }\n  participants {\n    accountKey\n    externalParticipantId\n    isApp\n    participantName\n    removed\n    role\n    __typename\n  }\n  userReadsInfo {\n    unreadCount\n    __typename\n  }\n  userLabelInfo {\n    labels\n    __typename\n  }\n  locks {\n    primary\n    reason\n    reasonCode\n    timestamp\n    endUserDisplayText\n    isRemovable\n    __typename\n  }\n  job {\n    key\n    displayTitle\n    normalizedTitle\n    title\n    employer {\n      key\n      name\n      dossier {\n        images {\n          squareLogoUrls {\n            url64\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      __typename\n    }\n    location {\n      formatted {\n        short\n        __typename\n      }\n      __typename\n    }\n    sourceEmployerName\n    __typename\n  }\n  userContext {\n    participantKey\n    requireResponse @include(if: $includeRequireResponse) {\n      required\n      timestamp\n      __typename\n    }\n    __typename\n  }\n  jobIsConfirmedFraudulent\n}\n\nfragment ConversationEventListItemWithoutTimelineModuleResult on ConversationEvent {\n  id\n  cleanedMessageBody\n  type\n  messageBody\n  messageContentFormat\n  messagePreview\n  metadata {\n    key\n    value\n    __typename\n  }\n  publicationDateTime\n  payload {\n    key\n    value\n    __typename\n  }\n  attachments {\n    contentHash\n    fileSid\n    fileName\n    fileExtension\n    __typename\n  }\n  author {\n    accountKey\n    externalParticipantId\n    role\n    __typename\n  }\n  subType\n  __typename\n}\n";
/** updateCandidateStatus
 * variables: {statusInput: {move: {milestoneId, candidateSubmissionEmployerJobIdPairs: [{candidateSubmissionId, jobId}]}}}
 */
export const updateCandidateStatus = "mutation UpdateCandidateStatus($statusInput: UpdateCandidateSubmissionMilestoneInput!) {\n  updateCandidateSubmissionMilestone(input: $statusInput) {\n    candidateSubmissionMilestone {\n      category\n      milestoneId\n      __typename\n    }\n    __typename\n  }\n}\n";
/** createCandidateNote
 * variables: {createEmployerCandidateSubmissionFeedbackInput: {candidateSubmissionIds, comment, source: {eventType: "NOTE"}}}
 */
export const createCandidateNote = "mutation CreateEmployerCandidateSubmissionNoteFeedback($createEmployerCandidateSubmissionFeedbackInput: CreateEmployerCandidateSubmissionFeedbackInput!) {\n  createEmployerCandidateSubmissionFeedback(\n    input: $createEmployerCandidateSubmissionFeedbackInput\n  ) {\n    feedback {\n      id\n      created\n      createdBy {\n        id\n        employer {\n          id\n          name\n          __typename\n        }\n        __typename\n      }\n      metaData {\n        candidateSource {\n          product\n          event {\n            name\n            __typename\n          }\n          __typename\n        }\n        __typename\n      }\n      ... on EmployerCandidateComment {\n        feedbackText\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n}\n";
